// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether for constructor
        vm.deal(address(this), 1 ether);
        // But C is already deployed in setUp with 1 ether
        // So we need to deal an actor
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);

        // First call to lockInGuess – in reference, it succeeds; in bug, it reverts
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", bytes32(uint256(0x1234))));

        // The reference contract: first call succeeds (ok1 == true)
        // The buggy contract:   first call reverts (ok1 == false) because block != 0 when it's 0
        assertTrue(ok1);
    }
}

