pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 2 ether for reference: 1 from deploy + 1 from first lockInGuess
        // But deploy already gives 1 ether; fund actor with 2 ether to cover two calls
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        vm.deal(address(c), 1 ether); // extra ether for eventual settle payout, not needed for lockInGuess revert check

        // First lockInGuess should succeed in both reference and buggy
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256("first"));

        // Second lockInGuess: reference (==0) allows it (block gets updated), buggy (!=0) reverts
        vm.prank(actor);
        bool ok = false;
        try c.lockInGuess{value: 1 ether}(keccak256("second")) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, second call succeeds (ok true); in buggy, it reverts (ok false)
        assertTrue(ok);
    }
}

