// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.deal(address(0x2), 1 ether);
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(keccak256("guess1"));
        vm.prank(address(0x2));
        c.lockInGuess{value: 1 ether}(keccak256("guess2"));
        // Now the reference will allow address(0x1) to call lockInGuess again (revert because block != 0)
        // Buggy version (require guesses[msg.sender].block != 0) will revert for a new caller, but here we test second call by same sender
        // Instead test: buggy version allows overwrite because condition passes (block != 0 is true after first call)
        // Reference rejects overwrite because it checks block == 0 (false after first call)
        // We can test via revert behavior: wrap second call by address(0x1)
        bool ok;
        vm.prank(address(0x1));
        try c.lockInGuess{value: 1 ether}(keccak256("guess3")) { ok = true; } catch { ok = false; }
        // In reference: revert -> ok = false. In buggy: success -> ok = true.
        // Since reference is correct, we assert ok == false (i.e., the reference behavior)
        assertTrue(ok == false);
    }
}

