pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        vm.deal(address(this), 2 ether);
        c = new C(); 
    }

    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));

        vm.deal(address(0x2), 1 ether);
        vm.prank(address(0x2));
        try c.lockInGuess{value: 1 ether}(bytes32(uint256(2))) {
            // buggy version succeeds (wrong)
        } catch {
            // reference reverts: require(block != 0) fails because block == 0 for new sender
        }

        // The buggy version allows the second lockInGuess (succeeding), so 1 ether is sent to c.
        // The reference reverts, so only the first 1 ether is in c.
        // But we need an observable difference: after the second call attempt, c has balance 2 ether in buggy, 2 ether in reference? 
        // Actually both have 2 ether because constructor takes 1 + first lock takes 1 = 2, and second does not change balance if it reverts? 
        // Let's instead check the state of guess for address(0x2) – both have a getter for the struct? No, struct mappings don't generate getters.
        // Use a scenario where balance diverges: after two successful locks (reference allows two from different senders? Actually reference allows first call only, second from different sender also first call – reference allows it. Buggy allows first call? Wait, buggy requires block != 0 for sender, so for address(0x2) block==0, require fails -> revert. So buggy reverts, reference succeeds. So balance differs: reference c gets 1 more ether.
        // Redo: 
        vm.deal(address(0x3), 1 ether);
        vm.prank(address(0x3));
        try c.lockInGuess{value: 1 ether}(bytes32(uint256(3))) {
            // reference: succeeds, c balance increases by 1
        } catch {
            // buggy: reverts
        }

        assertTrue(address(c).balance == 3 ether); 
        // In reference: constructor (1) + first lock (1) + third lock (1) = 3 ether.
        // In buggy: constructor (1) + first lock (1) = 2 ether, third lock reverts -> balance = 2 ether.
        // So assert passes for reference (3 == 3) and fails for buggy (2 != 3).
    }
}

