pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Player has 1 ether to lock in
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        // Block number 10
        vm.roll(10);
        // Call lockInGuess with the hash of block 10 (but reference stores block 11)
        bytes32 currentBlockHash = blockhash(10);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(currentBlockHash);
        // Advance to block 11 so settling is allowed in the reference
        vm.roll(11);
        vm.prank(player);
        c.settle();
        // In the reference: answer = blockhash(11) which is 0 (since roll(11) didn't set a real hash), so player gets nothing
        // In the bug: answer = blockhash(10) which is currentBlockHash, so player gets 2 ether
        // Therefore, player's balance differs: 0 in reference, 2 ether in bug
        assertTrue(address(player).balance == 0 ether);
    }
}

