pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: fund the contract with 1 ether (already done via constructor)
        // Fund an EOA with 1 ether to call lockInGuess
        address player = address(0xBEEF);
        vm.deal(player, 1 ether);
        vm.deal(address(c), 1 ether); // ensure contract has 2 ether total for payout

        // Warp to block 1, record its blockhash
        vm.roll(1);
        bytes32 blockHash = blockhash(1);

        // Player calls lockInGuess with the current block's hash
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(blockHash);

        // Now move to block 3 (more than block.number stored)
        vm.roll(3);

        // Player calls settle
        vm.prank(player);
        c.settle();

        // Check: In the reference, block stored was 2 (block.number+1), blockhash(2) is 0, so no transfer.
        // In the buggy version, block stored was 1, blockhash(1) matches guess, so transfer happens.
        // The contract balance decreases by 2 ether if transfer happened.
        // We compare to the initial balance (should be 2 ether after constructor take 1 from deployer).
        // But easier: address(c).balance should be 2 ether if no transfer, 0 ether if transfer happened.
        // For the buggy version, address(c).balance will be 0 ether; for reference, it stays 2 ether.
        assertTrue(address(c).balance < 2 ether, "Bug: settle succeeded, contract balance dropped");
    }
}

