pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether for deployment (done in constructor)
        vm.deal(address(c), 1 ether);

        // Set current block number to something predictable
        vm.roll(100);
        vm.warp(100 * 15); // arbitrary consistent timestamp

        // The current blockhash (of block 100) will be known after vm.roll
        bytes32 currentBlockHash = blockhash(100);

        // Call lockInGuess with that hash
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(currentBlockHash);

        // Move to next block so settle can be called
        vm.roll(101);

        // For reference: blockhash(100) is still available (within 256 blocks)
        // Reference stores block.number+1 = 101, blockhash(101) is not set yet (would be 0)
        // Bug stores block.number = 100, blockhash(100) matches

        uint256 balanceBefore = address(c).balance;
        vm.prank(player);
        c.settle();
        uint256 balanceAfter = address(c).balance;

        // In reference, no transfer -> balance unchanged (2 ether)
        // In bug, transfer 2 ether -> balance decreases by 2 ether
        // We assert the reference behavior: balance should remain 2 ether
        assertTrue(balanceAfter == balanceBefore, "Reference should not transfer");
    }
}

