pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Fund the contract with 1 ether via constructor (already done)
        // Fund an actor with 1 ether to call lockInGuess
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.deal(address(this), 1 ether);

        // Warp to block 1 so blockhash(1) is known (non-zero in this setup)
        vm.roll(1);
        vm.warp(1);

        // Compute the hash of block 1 (the current block)
        bytes32 currentHash = blockhash(block.number);

        // Alice calls lockInGuess with the current block's hash
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(currentHash);

        // Move to the next block so settle() will see block.number > stored block
        vm.roll(2);
        vm.warp(2);

        // Alice calls settle()
        vm.prank(alice);
        c.settle();

        // After settle, contract balance:
        // Reference: stored block.number+1 = 2, blockhash(2) = 0 => no transfer => balance = 2 ether
        // Buggy: stored block.number = 1, blockhash(1) = currentHash => transfer 2 ether => balance = 0
        // We assert that the balance is 2 ether (reference behavior) vs 0 (bug)
        assertTrue(address(c).balance == 2 ether);
    }
}

