pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // fund the contract with 1 ether via constructor already done
        // also deal the contract extra 1 ether so it starts with 2 ether total
        vm.deal(address(c), 2 ether);

        // first caller: lock in a guess with 1 ether
        address alice = address(0x1);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encode(1)));

        // alice calls lockInGuess again with 2 ether (more than 1) and a different hash
        vm.prank(alice);
        // in P: require(guesses[alice].block == 0) fails → revert, no ether taken, balance still 2 ether
        // in M: require(msg.value == 1 ether) passes → ether taken (2 ether), then require(block==0) fails → revert, balance becomes 4 ether
        (bool ok, ) = address(c).call{value: 2 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", keccak256(abi.encode(2))));
        assertTrue(!ok); // both revert, but balance diverges
        // reference: balance = 2 ether (constructor 1 + first call 1, second call not taken)
        // bug: balance = 4 ether (constructor 1 + first call 1 + second call 2)
        assertEq(address(c).balance, 2 ether);
    }
}

