pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy with 1 ether
        vm.deal(address(c), 1 ether);
        // Ensure we have a blockhash that will be 0 (block.number 0 has no hash)
        vm.roll(0);
        // Warp to set a reasonable timestamp (not needed but harmless)
        vm.warp(1);
        // Fund caller
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(0xdeadbeef)));
        // Now warp to block > guesses[alice].block (which is 1)
        vm.roll(2);
        vm.warp(2);
        // Try to settle; use try/catch to capture revert vs success
        vm.prank(alice);
        try c.settle() {
            // If settle succeeded, reference would revert because blockhash(1) is 0
            // So success would be buggy behavior
        } catch {
            // revert expected for reference
        }
        // Assert: In the reference, blockhash(1) is 0, so the condition answer != 0 fails and no transfer.
        // In the bug, the condition skips the answer != 0 check, and since guess == answer (both 0), it transfers.
        // We assert that alice's balance did NOT increase (i.e., reference behavior):
        assertTrue(address(alice).balance == 1 ether);
    }
}

