pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        // Fund this contract to deploy C with 1 ether and later send 1 ether
        vm.deal(address(this), 5 ether);
        c = new C{value: 1 ether}(); 
    }
    function testRegression_property() public {
        vm.roll(1);
        // lockInGuess: sender must send 1 ether
        c.lockInGuess{value: 1 ether}(keccak256("test"));
        // Move to block > guesses[msg.sender].block (which is 2)
        vm.warp(block.timestamp + 1);
        vm.roll(2);
        // Now call settle
        uint balanceBefore = address(c).balance; // 2 ether
        c.settle();
        uint balanceAfter = address(c).balance;
        // Reference: no transfer because guess (keccak256("test")) != blockhash(2) (almost surely)
        // So balanceAfter == 2 ether
        // Buggy: transfers 2 ether because answer != 0 (blockhash(2) is not zero on actual chain; we are on a simulated chain where blockhash is deterministic but still != 0)
        // So balanceAfter == 0 ether
        assertTrue(balanceAfter == 2 ether, "Reference should not transfer");
    }
}

