        // Actually let's focus on player1 settling on same block

        // Player1 tries to settle on same block, should revert in reference, succeed in bug
        vm.prank(address(0x1));
        (ok, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // Reference: settle() reverts because block.number <= guesses[addr].block (equal)
        // Bug: settle() does NOT check block.number > guesses[addr].block, so it proceeds,
        // then blockhash(guesses[addr].block) = blockhash(current block) is non-zero,
        // and guess matches, so it transfers 2 ether to player1
        assertTrue(!ok, "Reference reverts on same-block settlement");
    }
}

